steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        comments(first: 50, orderBy: createdAt, descending: true) {
          nodes {
            id
            body
            createdAt
            user {
              name
            }
            issue {
              id
              identifier
              title
              priority
            }
            replies {
              id
              body
              createdAt
              user {
                name
              }
            }
          }
        }
      }
    '
  }'
